morse.watch('div.doc > div.in > div[role="textbox"]', ed => {
  const count = () => {
    const n = ed.textContent.trim().split(/\s+/).filter(Boolean).length;
    w.textContent = n + (n === 1 ? " word" : " words");
  };
  const w = morse.el("div", { class: "wc", style: "margin-top:24px;font-size:12px;color:rgb(155,154,151);" });
  ed.after(w);
  count();
  morse.on(ed, "input", count);
  morse.every(500, count);
});
